    /** Delete a message.
     * 删除消息。 */
    deleteMessage(input: DeleteMessageInput): Promise<void>;
    /** Clear a conversation's messages.
     * 清空会话消息。 */
    clearMessages(input: ConversationIdInput): Promise<void>;
    /** Get conversation metadata.
     * 读取会话元信息。 */
    getConversation(input: ConversationIdInput): Promise<ConversationMeta>;
    /** List conversations.
     * 列出会话。 */
    listConversations(input?: ListConversationsInput): Promise<ListConversationsResult>;
    /** Delete a conversation.
     * 删除会话。 */
    deleteConversation(input: ConversationIdInput): Promise<void>;
    /** Update conversation metadata.
     * 更新会话元信息。 */
    updateConversation(input: UpdateConversationInput): Promise<ConversationMeta>;
    /** Convert to OpenAI message format.
     * 转 OpenAI 消息格式。 */
