    /** LangGraph checkpointer (platform-injected; typed by the langgraph package).
     * LangGraph checkpointer（平台注入，类型由 langgraph 包定义）。 */
    langgraphCheckpointer: unknown;
    /** LangGraph store (platform-injected).
     * LangGraph store（平台注入）。 */
